<?php

declare(strict_types=1);

namespace Campanella\Lite\Render;

use Campanella\Lite\Exception\StorageException;
use Campanella\Lite\Routing\Urls;
use Campanella\Lite\Storage\FileStore;

/**
 * Generated files in the web root, and the manifest that lists them.
 *
 * Pages are listed in var/cache-manifest.json and cleared after every
 * change. Published files (images in several sizes, documents, media) have
 * their own list, var/files-manifest.json, because they are slow to make
 * again and rarely change; they are pruned instead.
 *
 * Every file the generator writes is recorded in the manifest.
 * Clearing the cache deletes exactly those files, so nothing else in the
 * web root (the front controller, assets, files put there by hand) is
 * ever touched. The generator also refuses to overwrite a file it did not
 * create.
 */
final class PageCache
{
    public const MANIFEST = 'cache-manifest.json';
    public const FILES_MANIFEST = 'files-manifest.json';

    public function __construct(
        private readonly FileStore $public,
        private readonly FileStore $var,
        private readonly string $manifest = self::MANIFEST,
    ) {
    }

    /**
     * Stores the HTML of a page address and returns the file it was written to.
     */
    public function store(string $path, string $html): string
    {
        $file = Urls::file($path);
        $this->claim($file);
        $this->public->write($file, $html);

        return $file;
    }

    /**
     * Copies a file into the web root at the given relative path and returns its absolute path.
     */
    public function storeFile(string $file, string $source): string
    {
        $this->claim($file);
        $this->public->import($file, $source);

        return $this->public->path($file);
    }

    /**
     * Deletes the generated files for which $keep returns false; returns how many.
     *
     * @param callable(string): bool $keep receives the path relative to the web root
     */
    public function prune(callable $keep): int
    {
        $files = $this->files();
        $kept = [];
        $deleted = 0;

        foreach ($files as $file) {
            if ($keep($file)) {
                $kept[] = $file;
                continue;
            }

            if ($this->public->delete($file)) {
                $deleted++;
            }

            $this->removeEmptyParents($file);
        }

        if ($deleted > 0 || count($kept) !== count($files)) {
            $this->saveManifest($kept);
        }

        return $deleted;
    }

    /**
     * Records a file as generated, refusing files that exist but were not generated.
     */
    private function claim(string $file): void
    {
        $files = $this->files();

        if (in_array($file, $files, true)) {
            return;
        }

        if ($this->public->exists($file)) {
            throw StorageException::unsafePath($file, 'the file exists and was not generated by Campanella Lite');
        }

        $files[] = $file;
        $this->saveManifest($files);
    }

    /**
     * Deletes every generated file and returns how many there were.
     */
    public function clear(): int
    {
        $files = $this->files();
        $deleted = 0;

        foreach ($files as $file) {
            if ($this->public->delete($file)) {
                $deleted++;
            }

            $this->removeEmptyParents($file);
        }

        $this->saveManifest([]);

        return $deleted;
    }

    /**
     * @return list<string> generated files, relative to the web root
     */
    public function files(): array
    {
        if (!$this->var->exists($this->manifest)) {
            return [];
        }

        $data = json_decode($this->var->read($this->manifest), true);

        return is_array($data) ? array_values(array_filter($data, 'is_string')) : [];
    }

    /**
     * @param list<string> $files
     */
    private function saveManifest(array $files): void
    {
        sort($files);
        $this->var->write($this->manifest, json_encode($files, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n");
    }

    private function removeEmptyParents(string $file): void
    {
        $directory = dirname($file);

        while ($directory !== '.' && $directory !== '' && $this->public->deleteDirectoryIfEmpty($directory)) {
            $directory = dirname($directory);
        }
    }
}
